properties.query:
let windowSize = 1h;

// S7: Imagery Hijack — UAVImagery_CL엔 SwarmId 없음, 전역 게이트
let S7Time = toscalar(
    UAVImagery_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType in ('unauthorized_access','feed_hijack')
    | summarize min(TimeGenerated));

// S79: Off-hours C4I — UAVC4I_CL엔 SwarmId 없음, 전역 게이트
let S79Time = toscalar(
    UAVC4I_CL
    | where TimeGenerated > ago(windowSize)
    | where hourofday(TimeGenerated) >= 23 or hourofday(TimeGenerated) < 5
    | summarize min(TimeGenerated));

// S105: Sybil Node Injection — UAVFleetState_CL, FleetId 사용, UnknownUavIdDetected로 대리 탐지
let S105 =
    UAVFleetState_CL
    | where TimeGenerated > ago(windowSize)
    | where UnknownUavIdDetected == true
    | extend Stage = 'S105', SwarmId = tostring(FleetId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S102: Consensus Poisoning — AnomalyScore 급등
let S102 =
    UAVFleetState_CL
    | where TimeGenerated > ago(windowSize)
    | where AnomalyScore > 0.7
    | extend Stage = 'S102', SwarmId = tostring(FleetId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

union S105, S102
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by SwarmId
| extend HasS7 = isnotnull(S7Time), HasS79 = isnotnull(S79Time)
| extend EffectiveStageCount = StageCount + toint(HasS7) + toint(HasS79)
| where EffectiveStageCount >= 3
| extend CampaignType = "C25_합의전복_Sybil_포이즈닝_위조영상_C4I위조"
| extend StepSummary = strcat("S7(전역)@", tostring(S7Time), " | S79(전역)@", tostring(S79Time), " | Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, SwarmId, StagesSeen, EffectiveStageCount, CampaignType, StepSummary, Severity
